from pathlib import Path
import hashlib,json,subprocess,time
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent
expressions=['(with-precision 2 (pr-str (let [x 1.0 f (fn [] (- x 1.234M))] (f))))', '(with-precision 2 (pr-str (let [x (identity 1.0) f (fn [] (- x 1.234M))] (f))))', '(with-precision 2 (pr-str ((fn [^double x] (- x 1.234M)) 1.0)))', '(with-precision 2 (pr-str ((fn [x] (let [y x f (fn [] (- y 1.234M))] (f))) 1.0)))', '(with-precision 2 (pr-str (loop [x 1.0 n 0] (if (zero? n) (recur 2.0 1) (- x 1.234M)))))', '(with-precision 2 (pr-str (loop [x 1.0 n 0] (let [f (fn [] (- x 1.234M))] (if (zero? n) (recur (identity x) 1) (f))))))', '(with-precision 2 (pr-str (do (defmacro subtractprobe [x y] (list (symbol "-") x y)) (subtractprobe 1.0 1.234M))))', '(with-precision 2 (pr-str ((fn [^long x ^long y] (- x y)) -9223372036854775808 -9223372036854775808)))', '(with-precision 2 (pr-str (- 1.0 1.234M 0.002M)))', '(with-precision 2 (pr-str (- -0.0 0N 0)))', '(with-precision 2 :rounding UNNECESSARY (pr-str (let [events (atom []) f -] [(try (- (do (swap! events conj :a) 1M) (do (swap! events conj :b) 1.234M) (do (swap! events conj :c) 1)) (catch Throwable e :error)) @events])))', '(with-precision 2 :rounding UNNECESSARY (pr-str (let [events (atom []) f -] [(try (f (do (swap! events conj :a) 1M) (do (swap! events conj :b) 1.234M) (do (swap! events conj :c) 1)) (catch Throwable e :error)) @events])))', "(with-precision 2 (pr-str (let [x 1.0 f (fn [] (-' x 1.234M))] (f))))", "(with-precision 2 (pr-str (let [x (identity 1.0) f (fn [] (-' x 1.234M))] (f))))", "(with-precision 2 (pr-str ((fn [^double x] (-' x 1.234M)) 1.0)))", "(with-precision 2 (pr-str ((fn [x] (let [y x f (fn [] (-' y 1.234M))] (f))) 1.0)))", "(with-precision 2 (pr-str (loop [x 1.0 n 0] (if (zero? n) (recur 2.0 1) (-' x 1.234M)))))", "(with-precision 2 (pr-str (loop [x 1.0 n 0] (let [f (fn [] (-' x 1.234M))] (if (zero? n) (recur (identity x) 1) (f))))))", '(with-precision 2 (pr-str (do (defmacro subtractprobe [x y] (list (symbol "-\'") x y)) (subtractprobe 1.0 1.234M))))', "(with-precision 2 (pr-str ((fn [^long x ^long y] (-' x y)) -9223372036854775808 -9223372036854775808)))", "(with-precision 2 (pr-str (-' 1.0 1.234M 0.002M)))", "(with-precision 2 (pr-str (-' -0.0 0N 0)))", "(with-precision 2 :rounding UNNECESSARY (pr-str (let [events (atom []) f -'] [(try (-' (do (swap! events conj :a) 1M) (do (swap! events conj :b) 1.234M) (do (swap! events conj :c) 1)) (catch Throwable e :error)) @events])))", "(with-precision 2 :rounding UNNECESSARY (pr-str (let [events (atom []) f -'] [(try (f (do (swap! events conj :a) 1M) (do (swap! events conj :b) 1.234M) (do (swap! events conj :c) 1)) (catch Throwable e :error)) @events])))", '(with-precision 2 (pr-str (let [x 1.0 f (fn [] (unchecked-subtract x 1.234M))] (f))))', '(with-precision 2 (pr-str (let [x (identity 1.0) f (fn [] (unchecked-subtract x 1.234M))] (f))))', '(with-precision 2 (pr-str ((fn [^double x] (unchecked-subtract x 1.234M)) 1.0)))', '(with-precision 2 (pr-str ((fn [x] (let [y x f (fn [] (unchecked-subtract y 1.234M))] (f))) 1.0)))', '(with-precision 2 (pr-str (loop [x 1.0 n 0] (if (zero? n) (recur 2.0 1) (unchecked-subtract x 1.234M)))))', '(with-precision 2 (pr-str (loop [x 1.0 n 0] (let [f (fn [] (unchecked-subtract x 1.234M))] (if (zero? n) (recur (identity x) 1) (f))))))', '(with-precision 2 (pr-str (do (defmacro subtractprobe [x y] (list (symbol "unchecked-subtract") x y)) (subtractprobe 1.0 1.234M))))', '(with-precision 2 (pr-str ((fn [^long x ^long y] (unchecked-subtract x y)) -9223372036854775808 -9223372036854775808)))']
source='(assert (= "1.12.6" (clojure-version)))\n'+''.join('(println (pr-str (pr-str (try '+e+' (catch Throwable e [:error (.getMessage e)])))))\n' for e in expressions)
(OUT/'subtraction-source-facts-oracle.clj').write_text(source)
prior=json.loads((ROOT/'results/m12-wide-wit/oracle-command.json').read_text());command=prior['command'][:-1]+[str(OUT/'subtraction-source-facts-oracle.clj')]
t=time.time();r=subprocess.run(command,cwd=ROOT,text=True,capture_output=True)
(OUT/'subtraction-source-facts-oracle.log').write_text(r.stdout+r.stderr)
(OUT/'subtraction-source-facts-oracle-command.json').write_text(json.dumps({'command':command,'exit_code':r.returncode,'seconds':time.time()-t,'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'jars':{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in prior['jars']}},indent=2)+'\n')
assert r.returncode==0,r.stderr
values=[json.loads(x) for x in r.stdout.splitlines()];assert len(values)==len(expressions)
(OUT/'subtraction-source-facts-cases.json').write_text(json.dumps(list(zip(expressions,values)),indent=2)+'\n')
for i,x in enumerate(values):print(i,x)
